"""textstats: tiny text analysis utilities."""


def word_count(text):
    """Return the number of whitespace-separated words in *text*."""
    return len(text.split())


def char_histogram(text):
    """Return a dict mapping each character in *text* to its occurrence count."""
    histogram = {}
    for char in text:
        histogram[char] = histogram.get(char, 0) + 1
    return histogram

