from textstats import char_histogram, word_count


def test_word_count_basic():
    assert word_count("hello world foo") == 3


def test_word_count_empty_string():
    assert word_count("") == 0


def test_word_count_collapses_whitespace():
    assert word_count("  one\t two\n\nthree  ") == 3


def test_histogram_counts_characters():
    assert char_histogram("aab") == {"a": 2, "b": 1}


def test_histogram_empty_string():
    assert char_histogram("") == {}


def test_histogram_handles_spaces_and_punctuation():
    result = char_histogram("a a!")
    assert result[" "] == 1
    assert result["!"] == 1
    assert result["a"] == 2


def test_word_count_matches_histogram_words():
    text = "alpha beta alpha"
    assert word_count(text) == sum(char_histogram(text).values()) - len(text) + \
        len(text.split())

